// This file was not generated by AI

use core::f32;
use std::{collections::VecDeque, fmt::Display};

use crate::process::{intermediate::Highlight, stitches::{HighlightConf, Metadata, StitchCommand}};


#[derive(Clone, Copy)]
pub enum Format {
    /// Start with a magic circle with <n> stitches
    MagicCircle(usize),
    /// Single crochet
    Sc,
    /// For the next <m> stitches, put a single crochet in each stitch
    RepSc(usize),
    /// Chain 1 (don't count) AND
    Chain,
    /// Put <n> Single crochets into this stitch
    Inc(usize),
    /// For the next <m> stitches, put <n> single crochets in each stitch
    RepInc(usize, usize),
    /// Work the next <n> stitches together
    Dec(usize),
    /// Work the next <n> stitches together, <m> times
    RepDec(usize, usize),
    /// Put <n-1> Single crochets into this stitch AND THEN work this stitch and the next <m> stitches together
    IncDec(usize, usize),
    /// Single crochet into this stitch AND THEN work this stitch and the next <n> stitches together
    ScDec(usize),
    /// Begin stuffing now, and keep adding more as you close the remaining rounds.
    /// You should have <m> stitches in this round.
    /// --- ROUND <n> ---
    StartStuffing(usize, usize),
    /// CAREFUL - check docs for more information
    /// Close off this round with a slip stitch into the first stitch (NOT the first chain).
    /// You should have <m> stitches in this round.
    /// --- ROUND <n> ---
    Row(usize, usize),
    /// Close off this round with a slip stitch into the first stitch (NOT the first chain).
    RowStuffing,
    /// Close off this round with a slip stitch.
    /// You should have <n> stitches in this round.
    /// --- ROUND 1 ---
    FirstRow(usize),
    /// You should have <n> stitches in the final round.
    /// Fasten off, leaving a tail about 15cm long
    FastenOff(usize),
    /// Check your work is stuffed firmly
    CheckStuffing,
    /// Thread the tail through the front loop of each of the remaining <n> stitches, then pull tight to close the hole
    ThreadTail(usize),
    /// Weave the end into the inside of your work
    WeaveEnd,
}

impl Format {
    pub const SEPERATOR: &str = ". ";

    pub fn from_intermediate(mut vec: VecDeque<StitchCommand>, metadata: Metadata) -> Vec<(Self, Vec<Highlight>)> {
        let final_highlights = metadata.final_highlights;
        let stitch_w_cm = metadata.calculator.relative_to_actual_cm(1.0, false);
        println!("{vec:?}");
        let mut result = Vec::new();
        let StitchCommand::MagicCircle(circle, highlights) = vec.pop_front().unwrap() else { panic!("Unexpected stitch") };
        result.push((Self::MagicCircle(circle), highlights));
        let StitchCommand::NextRow(highlights) = vec.pop_front().unwrap() else { panic!("Unexpected stitch") };
        result.push((Self::FirstRow(circle), highlights));
        let mut chain_needed = true;
        let mut stitches = 0;
        let mut row_number = 2;

        for item in vec {
            if chain_needed {
                result.push((Self::Chain, vec![item.get_highlights()[0]]));
                chain_needed = false;
            }

            match item {
                StitchCommand::Inc(n, mut highlights) => {
                    if n == 1 {
                        if let Some((Self::Sc, _)) = result.last() {
                            highlights.append(&mut result.pop().unwrap().1);
                            result.push((Self::RepSc(2), highlights));
                        } else if let Some((Self::RepSc(n), _)) = result.last() {
                            let n = *n;
                            highlights.append(&mut result.pop().unwrap().1);
                            result.push((Self::RepSc(n + 1), highlights));
                        } else {
                            result.push((Self::Sc, highlights))
                        }
                    } else {
                        if let Some((Self::Inc(np), _)) = result.last() && *np == n {
                            highlights.append(&mut result.pop().unwrap().1);
                            result.push((Self::RepInc(n, 2), highlights));
                        } else if let Some((Self::RepInc(np, m), _)) = result.last() && *np == n {
                            let m = *m;
                            highlights.append(&mut result.pop().unwrap().1);
                            result.push((Self::RepInc(n, m + 1), highlights));
                        } else {
                            result.push((Self::Inc(n), highlights))
                        }
                    }
                    stitches += n;
                },
                StitchCommand::Dec(n, mut highlights) => {
                    if let Some((Self::Dec(m), _)) = result.last() && n + 1 == *m {
                        highlights.append(&mut result.pop().unwrap().1);
                        result.push((Self::RepDec(n + 1, 2), highlights));
                    } else if let Some((Self::RepDec(np, m), _)) = result.last() && n + 1 == *np {
                        let m = *m;
                        highlights.append(&mut result.pop().unwrap().1);
                        result.push((Self::RepDec(n + 1, m + 1), highlights));
                    } else {
                        result.push((Self::Dec(n + 1), highlights))
                    }
                    stitches += 1;
                },
                StitchCommand::Skip(n, mut highlights) => {
                    if let Some((Self::Inc(m), _)) = result.last() {
                        let m = *m;
                        highlights.append(&mut result.pop().unwrap().1);
                        if m == 2 {
                            result.push((Self::ScDec(n), highlights));
                        } else {
                            result.push((Self::IncDec(m, n), highlights));
                        }
                    } else if let Some((Self::RepInc(m, r), _)) = result.last() {
                        let m = *m;
                        let r = *r;
                        let mut last_highlights = result.pop().unwrap().1;
                        let highlight = last_highlights.remove(0);
                        highlights.push(highlight);
                        if r == 2 {
                            result.push((Self::Inc(m), last_highlights));
                        } else {
                            result.push((Self::RepInc(m, r - 1), last_highlights));
                        }
                        if m == 2 {
                            result.push((Self::ScDec(n), highlights));
                        } else {
                            result.push((Self::IncDec(m, n), highlights));
                        }
                    } else {
                        panic!("Impossible")
                    }
                },
                StitchCommand::NextRow(highlights) => {
                    result.push((Self::Row(row_number, stitches), highlights));
                    row_number += 1;
                    stitches = 0;
                    chain_needed = true;
                },
                StitchCommand::MagicCircle(_n, _highlights) => panic!("Unexpected magic circle."),
            }
        }

        const STUFFING_DIAMETER_LIIMT_CM: f32 = 4.5;
        let threshold_diameter = STUFFING_DIAMETER_LIIMT_CM / stitch_w_cm;
        let threshold_circumference = f32::consts::PI * threshold_diameter;
        let mut inserted = false;
        let mut biggest_index = 0;
        let mut biggest_size = 0;
        for (i, opt_n) in result.iter().map(|v| if let Self::Row(n, _) = v.0 { Some(n) } else { None }).enumerate().rev().collect::<Vec<_>>() {
            if let Some(n) = opt_n {
                if n as f32 > threshold_circumference {
                    let Self::Row(n, m) = result[i].0 else { panic!("Impossible") };
                    result[i].0 = Self::RowStuffing;
                    result.insert(i + 1, (Self::StartStuffing(n, m), Vec::new()));
                    inserted = true;
                    break
                }
                if n > biggest_size {
                    biggest_index = i;
                    biggest_size = n;
                }
            }
        }

        if !inserted && let Self::Row(n, m) = result[biggest_index].0 {
            result[biggest_index].0 = Self::RowStuffing;
            result.insert(biggest_index + 1, (Self::StartStuffing(n, m), Vec::new()));
        }

        result.append(&mut vec![
            (
                Self::FastenOff(stitches),
                vec![Highlight(
                    final_highlights[final_highlights.len() - 1].into(),
                    final_highlights[0].into()
                )]
            ),
            (
                Self::CheckStuffing,
                vec![]
            ),
            (
                Self::ThreadTail(stitches),
                final_highlights.array_windows().cloned().map(|v| v.into()).collect::<Vec<_>>()
            ),
            (
                Self::WeaveEnd,
                vec![]
            )
        ]);

        result
    }

    pub fn get_conf(&self) -> HighlightConf {
        match self {
            Self::Row(n, m) => HighlightConf::new(String::new(), format!("\nThis round should have {m} stitches.\n--- ROUND {n} ---\n"), true, false),
            Self::FirstRow(n) => HighlightConf::new(String::new(), format!("\nThis round should have {n} stitches.\n--- ROUND 1 ---\n"), true, false),
            Self::FastenOff(n) => HighlightConf::new(format!(".\nThis round should have {n} stitches.\n"), String::new(), false, false),
            Self::CheckStuffing | Self::ThreadTail(_) | Self::WeaveEnd => HighlightConf::new(".\n".to_string(), String::new(), false, false),
            Self::Chain => HighlightConf::new(String::new(), " AND ".to_string(), true, false),
            Self::StartStuffing(n, m) => HighlightConf::new(".\n".to_string(), format!("\nThis round should have {m} stitches.\n--- ROUND {n} ---\n"), false, false),
            _ => HighlightConf::default()
        }
    }
}

impl Display for Format {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Format::MagicCircle(n) => write!(f, "Start with a magic circle with {n} stitches"),
            Format::Sc => write!(f, "Single crochet"),
            Format::RepSc(n) => write!(f, "For the next {n} stitches, put a single crochet in each stitch"),
            Format::Chain => write!(f, "Chain 1 (don't count)"),
            Format::Inc(n) => write!(f, "Put {n} Single crochets into this stitch"),
            Format::RepInc(n, m) => write!(f, "For the next {m} stitches, put {n} single crochets in each stitch"),
            Format::Row(_, _) => write!(f, "Close off this round with a slip stitch into the first stitch (NOT the first chain)"),
            Format::RowStuffing => write!(f, "Close off this round with a slip stitch into the first stitch (NOT the first chain)"),
            Format::FirstRow(_) => write!(f, "Close off this round with a slip stitch"),
            Format::FastenOff(_) => write!(f, "Fasten off, leaving a tail about 15cm long"),
            Format::CheckStuffing => write!(f, "Check your work is stuffed firmly"),
            Format::ThreadTail(n) => write!(f, "Thread the tail through the front loop of each of the remaining {n} stitches, then pull tight to close the hole"),
            Format::WeaveEnd => write!(f, "Weave the end into the inside of your work"),
            Format::Dec(n) => write!(f, "Work the next {n} stitches together"),
            Format::RepDec(n, m) => write!(f, "Work the next {n} stitches together, {m} times"),
            Format::IncDec(n, m) => write!(f, "Put {} Single crochets into this stitch AND THEN work this stitch and the next {m} stitches together", n - 1),
            Format::ScDec(n) => write!(f, "Single crochet into this stitch AND THEN work this stitch and the next {n} stitches together"),
            Format::StartStuffing(_, _) => write!(f, "Begin stuffing now, and keep adding more as you close the remaining rounds"),
        }
    }
}